variante_1.css:
.sl-toc {
  position: sticky;
  top: 20px; /* Ajuste conforme necessário para o cabeçalho */
  z-index: 100;
  background-color: var(--sl-card-bg);
  border-color: var(--sl-border);
}

.sl-toc .card-header {
  background-color: var(--sl-card-bg);
  border-bottom: 1px solid var(--sl-border);
}

.sl-toc .card-title {
  color: var(--sl-text-main);
}

.sl-toc .list-group-item {
  border: none;
  padding: 0.5rem 1rem;
  background-color: transparent;
}

.sl-toc .list-group-item a {
  display: block;
  padding: 0.25rem 0;
  color: var(--sl-text-main);
  text-decoration: none;
  transition: color 0.2s ease-in-out;
}

.sl-toc .list-group-item a:hover {
  color: var(--sl-primary);
}

.sl-toc .list-group-item a.active {
  color: var(--sl-primary);
  font-weight: 600;
  position: relative;
}

.sl-toc .list-group-item a.active::before {
  content: '';
  position: absolute;
  left: -1rem;
  top: 50%;
  transform: translateY(-50%);
  width: 4px;
  height: 80%;
  background-color: var(--sl-primary);
  border-radius: 2px;
}

.sl-toc .list-group-item.h3-item {
  padding-left: 2rem;
}

@media (max-width: 767.98px) {
  .sl-toc {
    position: static;
  }
  .sl-toc .card-header {
    border-bottom: none;
  }
  .sl-toc .card-body {
    border-top: 1px solid var(--sl-border);
  }
}

