document.addEventListener('DOMContentLoaded', () => {
  const contentBlock = document.querySelector('.entry-content, .sl-post-content');
  const tocList = document.getElementById('sl-toc-list');
  const slToc = document.getElementById('sl-toc');

  if (!contentBlock || !tocList || !slToc) {
    if (!slToc) console.warn('sl-toc element not found. TOC will not be generated.');
    if (!contentBlock) console.warn('Content block (.entry-content or .sl-post-content) not found. TOC will not be generated.');
    if (!tocList) console.warn('sl-toc-list element not found. TOC will not be generated.');
    return;
  }

  const headings = contentBlock.querySelectorAll('h2, h3');
  if (headings.length === 0) {
    slToc.style.display = 'none'; // Hide TOC if no headings
    return;
  }

  let h2Counter = 0;
  const h3Counters = {};
  const observerOptions = {
    root: null,
    rootMargin: '0px 0px -70% 0px', // Triggers when element enters top 30% of viewport
    threshold: 0
  };

  const observer = new IntersectionObserver((entries) => {
    let activeId = null;
    // Find the first intersecting entry from the top of the viewport's active zone
    for (let i = 0; i < entries.length; i++) {
      if (entries[i].isIntersecting) {
        activeId = entries[i].target.id;
        break; // Take the first one that intersects the rootMargin from the top
      }
    }

    // Fallback: if no element is currently intersecting the rootMargin (e.g., scrolled past all, or between sections)
    // Find the last heading that is completely above the viewport.
    if (!activeId) {
      for (let i = headings.length - 1; i >= 0; i--) {
        if (headings[i].getBoundingClientRect().bottom < 0) { // If the bottom of the heading is above the viewport top
          activeId = headings[i].id;
          break;
        }
      }
    }

    // If still no activeId (e.g., at the very top of the page before first heading)
    // and the first heading is below the viewport's active zone, ensure no link is active.
    if (!activeId && headings.length > 0 && headings[0].getBoundingClientRect().top > window.innerHeight * 0.3) {
        activeId = null; // Clear active if at the very top and first heading is not yet in view
    }

    document.querySelectorAll('#sl-toc-list a').forEach(link => {
      link.classList.remove('active');
    });

    if (activeId) {
      const activeLink = document.querySelector(`#sl-toc-list a[href="#${activeId}"]`);
      if (activeLink) {
        activeLink.classList.add('active');
      }
    }
  }, observerOptions);

  headings.forEach(heading => {
    if (!heading.id) {
      heading.id = 'section-' + heading.textContent.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-*|-*$/g, '');
    }

    const listItem = document.createElement('li');
    listItem.classList.add('list-group-item');
    const link = document.createElement('a');
    link.href = `#${heading.id}`;

    let sectionNumber = '';
    if (heading.tagName === 'H2') {
      h2Counter++;
      sectionNumber = `${h2Counter}.`;
      h3Counters[h2Counter] = 0;
    } else if (heading.tagName === 'H3') {
      h3Counters[h2Counter]++;
      sectionNumber = `${h2Counter}.${h3Counters[h2Counter]}.`;
      listItem.classList.add('h3-item');
    }

    link.textContent = `${sectionNumber} ${heading.textContent}`;
    link.setAttribute('data-target-id', heading.id);

    link.addEventListener('click', (e) => {
      e.preventDefault();
      const targetId = e.target.getAttribute('href').substring(1);
      const targetElement = document.getElementById(targetId);
      if (targetElement) {
        targetElement.scrollIntoView({
          behavior: 'smooth',
          block: 'start'
        });
        // Optional: Update URL hash without page reload
        history.pushState(null, '', `#${targetId}`);
      }
    });

    listItem.appendChild(link);
    tocList.appendChild(listItem);

    observer.observe(heading);
  });

  // Initial active state check on load if hash is present
  const initialHash = window.location.hash.substring(1);
  if (initialHash) {
    const initialLink = document.querySelector(`#sl-toc-list a[href="#${initialHash}"]`);
    if (initialLink) {
      initialLink.classList.add('active');
    }
  }
});

